class Solution {public:
 long long maximumProfit(vector<int>& prices,int k){
  const long long NEG=LLONG_MIN/4;vector<long long> flat(k+1,NEG),longPos(k+1,NEG),shortPos(k+1,NEG);flat[0]=0;
  for(int p:prices){auto nf=flat,nl=longPos,ns=shortPos;
   for(int t=0;t<=k;++t){if(flat[t]!=NEG){nl[t]=max(nl[t],flat[t]-p);ns[t]=max(ns[t],flat[t]+p);}
    if(t<k){if(longPos[t]!=NEG)nf[t+1]=max(nf[t+1],longPos[t]+p);if(shortPos[t]!=NEG)nf[t+1]=max(nf[t+1],shortPos[t]-p);}
   }flat.swap(nf);longPos.swap(nl);shortPos.swap(ns);
  }return max(0LL,*max_element(flat.begin(),flat.end()));
 }
};
